<?php
require __DIR__.'/bootstrap.php';
if(method()==='GET'){$pid=int_value($_GET['product_id']??null,'product');$stmt=$db->prepare("SELECT r.rating,r.comment,r.created_at,CONCAT(u.first_name,' ',LEFT(u.last_name,1),'.') author FROM reviews r JOIN users u ON u.id=r.reviewer_id WHERE r.product_id=? AND r.status='published' ORDER BY r.created_at DESC");$stmt->bind_param('i',$pid);ok(db_all($stmt));}
$u=require_user();$in=input();if(method()==='POST'){$item=int_value($in['order_item_id']??null,'order item');$rating=(int)($in['rating']??0);$comment=text_value($in,'comment',2000,false);if($rating<1||$rating>5)fail('Rating must be from 1 to 5.',422);$stmt=$db->prepare('SELECT oi.seller_id,oi.product_id FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.id=? AND o.buyer_id=? AND o.status=\'delivered\'');$stmt->bind_param('ii',$item,$u['id']);$row=db_one($stmt);if(!$row)fail('Only delivered purchases can be reviewed.',403);$stmt=$db->prepare('SELECT id FROM reviews WHERE order_item_id=?');$stmt->bind_param('i',$item);if(db_one($stmt))fail('This purchase has already been reviewed.',409);$stmt=$db->prepare('INSERT INTO reviews(order_item_id,reviewer_id,seller_id,product_id,rating,comment) VALUES(?,?,?,?,?,?)');$stmt->bind_param('iiiiis',$item,$u['id'],$row['seller_id'],$row['product_id'],$rating,$comment);$stmt->execute();ok(null,'Review published.',201);}fail('Method not allowed.',405);
